def _parse_time(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


@dataclass(frozen=True)
class GateScope:
    region: str = "*"
    universe: str = "*"
    delay: int | str = "*"
    alpha_type: str = "*"
    theme_id: str = "*"
    pyramid_id: str = "*"

    def values(self) -> tuple[str, ...]:
        return tuple(str(value).upper() if index < 4 else str(value) for index, value in enumerate((self.region, self.universe, self.delay, self.alpha_type, self.theme_id, self.pyramid_id)))


@dataclass(frozen=True)
class GateSnapshot:
    snapshot_key: str
    gate_name: str
    limit: float
    direction: str
    scope: GateScope
    first_seen_at: str
    last_seen_at: str
    observation_count: int
    source: str
    raw_payload_hash: str
    version: int


class MissingGateSnapshot(LookupError):
    pass


class StaleGateSnapshot(RuntimeError):
    pass


class GateRegistry:
    def __init__(self, database: str | Path, *, freshness_hours: float = 24.0) -> None:
        self.database = Path(database)
        self.freshness_hours = float(freshness_hours)

    @staticmethod
    def _snapshot_key(observation: GateObservation) -> str:
        values = (observation.gate_name, observation.region, observation.universe, observation.delay, observation.alpha_type, observation.theme_id, observation.pyramid_id)
        return "|".join(values)

    def record(self, observation: GateObservation) -> None:
        self.record_many([observation])

    def record_many(self, observations: Iterable[GateObservation]) -> int:
        rows = list(observations)
        if not rows:
            return 0
        inserted = 0
        with sqlite3.connect(self.database) as con:
            for item in rows:
                cursor = con.execute("""INSERT OR IGNORE INTO platform_gate_observations
                    (observation_id,gate_name,result,limit_value,observed_value,message,direction,region,universe_name,delay,alpha_type,theme_id,pyramid_id,source_alpha_id,observed_at,ingested_at,raw_payload_hash,source,timestamp_source,freshness_eligible)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
                    item.observation_id,item.gate_name,item.result,item.limit,item.value,item.message,item.direction,
                    item.region,item.universe,item.delay,item.alpha_type,item.theme_id,item.pyramid_id,item.source_alpha_id,
                    item.observed_at,item.ingested_at,item.raw_payload_hash,item.source,item.timestamp_source,int(item.freshness_eligible),
                ))
                inserted += cursor.rowcount
                if item.limit is None or not item.observed_at or not item.freshness_eligible:
                    continue
                key = self._snapshot_key(item)
                current = con.execute("SELECT first_seen_at,last_seen_at,observation_count,version FROM platform_gate_snapshots WHERE snapshot_key=?", (key,)).fetchone()
                if current and _parse_time(str(current[1])) > _parse_time(item.observed_at):
                    continue
                first_seen = min(str(current[0]), item.observed_at) if current else item.observed_at
                count, version = (int(current[2]) + 1, int(current[3]) + 1) if current else (1, 1)
                con.execute("""INSERT INTO platform_gate_snapshots
                    (snapshot_key,gate_name,limit_value,direction,region,universe_name,delay,alpha_type,theme_id,pyramid_id,first_seen_at,last_seen_at,observation_count,source,raw_payload_hash,version)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(snapshot_key) DO UPDATE SET limit_value=excluded.limit_value,direction=excluded.direction,
                    first_seen_at=excluded.first_seen_at,last_seen_at=excluded.last_seen_at,observation_count=excluded.observation_count,
                    source=excluded.source,raw_payload_hash=excluded.raw_payload_hash,version=excluded.version""", (
                    key,item.gate_name,item.limit,item.direction,item.region,item.universe,item.delay,item.alpha_type,item.theme_id,item.pyramid_id,
                    first_seen,item.observed_at,count,item.source,item.raw_payload_hash,version,
                ))
        return inserted

    def resolve(self, scope: GateScope, gate_name: str) -> GateSnapshot | None:
        requested = scope.values()
        with sqlite3.connect(self.database) as con:
            rows = con.execute("""SELECT snapshot_key,gate_name,limit_value,direction,region,universe_name,delay,alpha_type,theme_id,pyramid_id,first_seen_at,last_seen_at,observation_count,source,raw_payload_hash,version
                FROM platform_gate_snapshots WHERE gate_name=?""", (gate_name.upper(),)).fetchall()
        matches = []
        for row in rows:
            stored = tuple(str(value) for value in row[4:10])
            if all(saved == "*" or saved.upper() == wanted.upper() for saved, wanted in zip(stored, requested)):
                specificity = sum(value != "*" for value in stored)
                matches.append((specificity, _parse_time(str(row[11])), row))
        if not matches:
            return None
        row = max(matches, key=lambda item: (item[0], item[1]))[2]
        return GateSnapshot(row[0], row[1], float(row[2]), row[3], GateScope(*row[4:10]), row[10], row[11], int(row[12]), row[13], row[14], int(row[15]))

    def require_fresh(self, scope: GateScope, gate_name: str, *, now: datetime | None = None) -> GateSnapshot:
        snapshot = self.resolve(scope, gate_name)
        if snapshot is None:
            raise MissingGateSnapshot(gate_name)
        current = now or datetime.now(timezone.utc)
        if current - _parse_time(snapshot.last_seen_at) > timedelta(hours=self.freshness_hours):
            raise StaleGateSnapshot(gate_name)
        return snapshot

    def export_snapshot(self, path: str | Path) -> int:
        with sqlite3.connect(self.database) as con:
            rows = con.execute("SELECT snapshot_key,gate_name,limit_value,direction,region,universe_name,delay,alpha_type,theme_id,pyramid_id,first_seen_at,last_seen_at,observation_count,source,raw_payload_hash,version FROM platform_gate_snapshots ORDER BY gate_name,snapshot_key").fetchall()
        payload = [{"snapshot_key": r[0], "gate_name": r[1], "limit": r[2], "direction": r[3], "scope": {"region": r[4], "universe": r[5], "delay": r[6], "alpha_type": r[7], "theme_id": r[8], "pyramid_id": r[9]}, "first_seen_at": r[10], "last_seen_at": r[11], "observation_count": r[12], "source": r[13], "raw_payload_hash": r[14], "version": r[15]} for r in rows]
        Path(path).write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        return len(payload)

"""Field catalog independent of pipeline orchestration."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from typing import Any, Iterable

from alpha_mining.common import to_float
from .operator_registry import BASE_VARS


def is_bad_field_name(field_name: str) -> bool:
    low = str(field_name or "").lower()
    if not low or low in BASE_VARS:
        return False
    tokens = ("currency", "country", "zipcode", "address", "url", "phone", "email", "ticker", "cusip", "isin", "sedol", "exchange", "sector_code", "industry_code", "date", "year", "quarter", "flag")
    return any(token in low for token in tokens) or low.endswith(("_id", "_code", "_cd", "_key"))


def is_weak_fundamental_field(field_name: str) -> bool:
    low = str(field_name or "").lower()
    weak = ("receivable", "inventory", "payable", "income_tax", "liabilit", "xidoc", "xrent", "txbco", "optca", "cld", "recd", "mrc1", "rdipa", "rent", "tax")
    return not low or any(token in low for token in weak) or ("guidance" in low and not any(x in low for x in ("ebitda", "eps", "sales", "revenue", "profit")))


def field_quality_score(field_name: str) -> float:
    low = str(field_name or "").lower()
    good = ("sales", "revenue", "income", "profit", "ebit", "cashflow", "asset", "debt", "equity", "book", "margin", "expense", "capex", "accrual", "dividend", "shares", "operating", "eps")
    score = sum(1.0 for token in good if token in low)
    score += 0.5 if "estimate" in low or "guidance" in low else 0.0
    score += 0.25 if low.startswith(("mdf_", "fnd6_", "fn_", "fundamental")) else 0.0
    return min(score, 5.0)


@dataclass
class FieldCatalog:
    df: Any
    ids: set[str]
    by_ds: dict[str, list[str]]
    fund: list[str]
    analyst: list[str]
    model: list[str]
    sent: list[str]
    pv: list[str]
    other: list[str]
    base_vars: set[str] = field(default_factory=lambda: set(BASE_VARS))
    field_dataset: dict[str, str] = field(default_factory=dict)
    field_user_count: dict[str, float] = field(default_factory=dict)

    @classmethod
    def from_df(cls, df: Any) -> "FieldCatalog":
        ids: set[str] = set()
        by_ds: dict[str, list[str]] = defaultdict(list)
        pools = {name: [] for name in ("fund", "analyst", "model", "sent", "pv", "other")}
        datasets: dict[str, str] = {}
        users: dict[str, float] = {}
        for _, row in df.iterrows():
            fid, ds = str(row.get("id", "")).strip(), str(row.get("_ds", "")).lower()
            if not fid:
                continue
            ids.add(fid); by_ds[ds].append(fid); datasets[fid] = ds; users[fid] = to_float(row.get("userCount")) or 0.0
            low = fid.lower()
            if "fundamental" in ds or any(x in low for x in ("sales", "revenue", "income", "profit", "asset", "debt", "cash", "eps")):
                pool = "fund"
            elif "analyst" in ds or any(x in low for x in ("analyst", "estimate", "forecast", "revision")):
                pool = "analyst"
            elif "model" in ds or low.startswith("mdl"):
                pool = "model"
            elif any(x in ds for x in ("sentiment", "news", "social")):
                pool = "sent"
            elif ds.startswith("pv") or fid in BASE_VARS or any(x in low for x in ("close", "volume", "vwap", "return", "price")):
                pool = "pv"
            else:
                pool = "other"
            pools[pool].append(fid)
        return cls(df, ids, dict(by_ds), *(list(dict.fromkeys(pools[k])) for k in ("fund", "analyst", "model", "sent", "pv", "other")), field_dataset=datasets, field_user_count=users)

    def best(self, pools: Iterable[list[str]], tokens: tuple[str, ...] = ()) -> str | None:
        fields = list(dict.fromkeys(f for pool in pools for f in pool if f and not is_bad_field_name(f)))
        fields.sort(key=lambda f: (sum(token in f.lower() for token in tokens), field_quality_score(f), f), reverse=True)
        return fields[0] if fields else None

    def replacement_for(self, field_name: str) -> str | None:
        pool = next((p for p in (self.fund, self.analyst, self.model, self.sent, self.pv, self.other) if field_name in p), [])
        choices = [f for f in pool if f != field_name and self.field_dataset.get(f) != self.field_dataset.get(field_name)]
        choices.sort(key=lambda f: (field_quality_score(f), -self.field_user_count.get(f, 0.0), f), reverse=True)
        return choices[0] if choices else None

"""Small, deterministic FASTEXPR syntax tree used for feature extraction."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass

_TOKEN = re.compile(r"\s*(?:(\d+(?:\.\d+)?)|([A-Za-z_][A-Za-z0-9_]*)|(.))")


@dataclass(frozen=True)
class AstNode:
    kind: str
    value: str
    children: tuple["AstNode", ...] = ()

    def as_dict(self) -> dict:
        return {"kind": self.kind, "value": self.value, "children": [child.as_dict() for child in self.children]}

    def to_json(self) -> str:
        return json.dumps(self.as_dict(), ensure_ascii=False, sort_keys=True, separators=(",", ":"))


class ExpressionSyntaxError(ValueError):
    pass


class _Parser:
    def __init__(self, text: str) -> None:
        self.tokens = [(number and "number" or ident and "ident" or "symbol", number or ident or symbol)
                       for number, ident, symbol in _TOKEN.findall(text)]
        self.index = 0

    def peek(self) -> tuple[str, str] | None:
        return self.tokens[self.index] if self.index < len(self.tokens) else None

    def take(self, value: str | None = None) -> tuple[str, str]:
        token = self.peek()
        if token is None or (value is not None and token[1] != value):
            raise ExpressionSyntaxError(f"expected {value or 'token'}")
        self.index += 1
        return token

    def expression(self, minimum: int = 0) -> AstNode:
        token = self.take()
        if token[1] in {"+", "-"}:
            left = AstNode("unary", token[1], (self.expression(30),))
        elif token[1] == "(":
            left = self.expression()
            self.take(")")
        elif token[0] == "ident" and self.peek() and self.peek()[1] == "(":
            self.take("(")
            args: list[AstNode] = []
            if not self.peek() or self.peek()[1] != ")":
                while True:
                    args.append(self.expression())
                    if not self.peek() or self.peek()[1] != ",":
                        break
                    self.take(",")
            self.take(")")
            left = AstNode("call", token[1].lower(), tuple(args))
        else:
            left = AstNode(token[0], token[1].lower())
        precedence = {"+": 10, "-": 10, "*": 20, "/": 20, "^": 25}
        while self.peek() and self.peek()[1] in precedence and precedence[self.peek()[1]] >= minimum:
            operator = self.take()[1]
            left = AstNode("binary", operator, (left, self.expression(precedence[operator] + 1)))
        return left


def parse_expression(expression: str) -> AstNode:
    parser = _Parser(str(expression or ""))
    if not parser.tokens:
        raise ExpressionSyntaxError("empty expression")
    node = parser.expression()
    if parser.peek() is not None:
        raise ExpressionSyntaxError(f"unexpected token {parser.peek()[1]}")
    return node


def depth(node: AstNode) -> int:
    return 1 + max((depth(child) for child in node.children), default=0)

"""Independent preflight validation for consultant expressions."""

from __future__ import annotations

import re
from dataclasses import dataclass

from .expression_normalization import extract_fields, extract_functions
from .field_catalog import FieldCatalog
from .operator_registry import BLOCKED_FUNCTIONS, FUNCTIONS, GROUPS


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    message: str
    severity: str = "error"


class PreflightValidator:
    def __init__(self, catalog: FieldCatalog | None = None, *, min_ts_corr_window: int = 10) -> None:
        self.catalog = catalog
        self.min_ts_corr_window = max(1, int(min_ts_corr_window))

    def issues(self, expression: str) -> tuple[ValidationIssue, ...]:
        text = str(expression or "").strip().lower()
        out: list[ValidationIssue] = []
        if not text:
            return (ValidationIssue("EMPTY", "empty expression"),)
        if any(x in text for x in ("http://", "https://", "www.", ".com")):
            out.append(ValidationIssue("URL_TOKEN", "URL-like token"))
        blocked = sorted(set(extract_functions(text)) & BLOCKED_FUNCTIONS)
        if blocked or re.search(r"[<>=!]=|[<>]", text):
            out.append(ValidationIssue("SPARSE_CONDITIONAL", ",".join(blocked) or "conditional operator"))
        unknown_ops = sorted(set(extract_functions(text)) - FUNCTIONS)
        if unknown_ops:
            out.append(ValidationIssue("UNKNOWN_OPERATOR", ",".join(unknown_ops)))
        for match in re.finditer(r"ts_corr\([^)]*,\s*(\d+)\s*\)", text):
            if int(match.group(1)) < self.min_ts_corr_window:
                out.append(ValidationIssue("SHORT_CORRELATION_WINDOW", match.group(1)))
        if self.catalog:
            unknown = [field for field in extract_fields(text) if field not in self.catalog.ids and field not in GROUPS]
            if unknown:
                out.append(ValidationIssue("UNKNOWN_FIELD", ",".join(unknown[:8])))
        return tuple(out)

    def validate(self, expression: str) -> tuple[bool, str]:
        issues = self.issues(expression)
        return (not issues, "ok" if not issues else f"{issues[0].code.lower()}:{issues[0].message}")

