from __future__ import annotations

import hashlib
import re
from typing import Any

from alpha_mining.common import sig
from .operator_registry import BASE_VARS, FUNCTIONS, GROUPS, LITERALS

_NUMBER = re.compile(r"(?<![a-z_])[-+]?\d+(?:\.\d+)?(?:e[-+]?\d+)?", re.I)


def extract_functions(expression: str) -> list[str]:
    return re.findall(r"\b([a-z_][a-z0-9_]*)\s*\(", str(expression or "").lower())


def extract_identifiers(expression: str) -> list[str]:
    return re.findall(r"\b[a-z_][a-z0-9_]*\b", str(expression or "").lower())


def extract_fields(expression: str) -> list[str]:
    excluded = FUNCTIONS | GROUPS | BASE_VARS | LITERALS
    return list(dict.fromkeys(token for token in extract_identifiers(expression) if token not in excluded))


def exact_hash(expression: str) -> str:
    return hashlib.sha256(sig(expression).encode("utf-8")).hexdigest()


def normalized_expression(expression: str) -> str:
    text = sig(expression).lower()
    text = _NUMBER.sub("#", text)
    return re.sub(r"\s+", "", text)


def _strip_outer(text: str) -> str:
    text = text.strip()
    while text.startswith("(") and text.endswith(")"):
        depth = 0
        complete = True
        for index, char in enumerate(text):
            depth += 1 if char == "(" else -1 if char == ")" else 0
            if depth == 0 and index != len(text) - 1:
                complete = False
                break
        if not complete or depth:
            break
        text = text[1:-1].strip()
    return text


def operator_topology(expression: str) -> str:
    text = normalized_expression(expression)
    reserved = FUNCTIONS | GROUPS | BASE_VARS
    text = re.sub(
        r"\b[a-z_][a-z0-9_]*\b",
        lambda m: m.group(0) if m.group(0) in reserved else "field",
        text,
    )
    return text


def _behavior_topology(expression: str) -> str:
    text = _strip_outer(operator_topology(expression))
    # Whole-expression sign and scalar multiplication do not change behavior risk.
    for _ in range(4):
        changed = False
        if text.startswith("-(") and text.endswith(")"):
            text = _strip_outer(text[1:])
            changed = True
        elif text.startswith("-"):
            text = _strip_outer(text[1:])
            changed = True
        scalar = re.match(r"^#\*\((.*)\)$", text)
        if scalar:
            text = _strip_outer(scalar.group(1))
            changed = True
        scalar = re.match(r"^\((.*)\)\*#$", text)
        if scalar:
            text = _strip_outer(scalar.group(1))
            changed = True
        if not changed:
            break
    text = re.sub(r"(?<=\))[-+]#$", "", text)
    text = re.sub(r"(?<=\w)[-+]#$", "", text)
    text = re.sub(r"\*-?#", "", text)
    text = text.replace("-rank(", "rank(").replace("+-", "+").replace("--", "")
    return _strip_outer(text)


def behavior_signature(expression: str, *, settings: dict[str, Any] | None = None) -> str:
    del settings
    if not sig(expression):
        return ""
    fields = "|".join(sorted(extract_fields(expression))[:8]) or "-"
    return f"{fields}::{_behavior_topology(expression)}"


def structure_signature(expression: str) -> str:
    functions = ">".join(extract_functions(expression)[:12]) or "raw"
    fields = "|".join(sorted(extract_fields(expression))[:8]) or "-"
    return f"{functions}::{fields}::{operator_topology(expression)}"


# Legacy-compatible names.
_normalized_expression = normalized_expression
_structure_signature = structure_signature
_behavior_signature = behavior_signature

"""Level-2 aligned returns correlation calculations."""

from __future__ import annotations

import math
from dataclasses import dataclass


def _pearson(left: list[float], right: list[float]) -> float | None:
    if len(left) != len(right) or len(left) < 2:
        return None
    ml, mr = sum(left) / len(left), sum(right) / len(right)
    dl, dr = [v - ml for v in left], [v - mr for v in right]
    denominator = math.sqrt(sum(v*v for v in dl) * sum(v*v for v in dr))
    return sum(a*b for a,b in zip(dl,dr)) / denominator if denominator else None


def _ranks(values: list[float]) -> list[float]:
    indexed = sorted(enumerate(values), key=lambda item: (item[1], item[0]))
    ranks = [0.0] * len(values)
    index = 0
    while index < len(indexed):
        end = index + 1
        while end < len(indexed) and indexed[end][1] == indexed[index][1]:
            end += 1
        rank = (index + end - 1) / 2 + 1
        for cursor in range(index, end):
            ranks[indexed[cursor][0]] = rank
        index = end
    return ranks


@dataclass(frozen=True)
class CorrelationResult:
    status: str
    overlap: int
    pearson: float | None
    spearman: float | None
    absolute_correlation: float | None
    behavior_risk: bool


class CorrelationService:
    def __init__(self, *, min_overlap: int = 60, internal_limit: float = 0.65) -> None:
        self.min_overlap = max(2, int(min_overlap))
        self.internal_limit = float(internal_limit)

    def compare(self, candidate: list[tuple[str, float]], reference: list[tuple[str, float]]) -> CorrelationResult:
        left, right = dict(candidate), dict(reference)
        dates = sorted(set(left) & set(right))
        if len(dates) < self.min_overlap:
            return CorrelationResult("INSUFFICIENT_HISTORY", len(dates), None, None, None, False)
        a, b = [float(left[d]) for d in dates], [float(right[d]) for d in dates]
        pearson, spearman = _pearson(a,b), _pearson(_ranks(a),_ranks(b))
        absolute = max(abs(value) for value in (pearson,spearman) if value is not None)
        return CorrelationResult("PASS", len(dates), pearson, spearman, absolute, absolute >= self.internal_limit)

"""Streaming importer for legacy CSV and embedded platform JSON."""

from __future__ import annotations

import csv
import hashlib
import json
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Iterable, Mapping

from alpha_mining.common import to_float
from alpha_mining.platform.check_parser import parse_gate_observations
from alpha_mining.platform.gates import GateRegistry
from .features import ExpressionFeatures, extract_features

SENSITIVE_KEYS = frozenset({"authorization", "cookie", "set-cookie", "password", "passwd", "token", "api_key", "apikey", "username", "email"})


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def sanitize_payload(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): "[REDACTED]" if str(key).lower() in SENSITIVE_KEYS else sanitize_payload(item) for key, item in value.items()}
    if isinstance(value, list):
        return [sanitize_payload(item) for item in value]
    return value


def json_object(value: Any, default: Any) -> Any:
    if isinstance(value, (dict, list)):
        return sanitize_payload(value)
    try:
        parsed = json.loads(str(value or ""))
    except Exception:
        return default
    return sanitize_payload(parsed)


def _normalized_row(row: Mapping[str, Any]) -> dict[str, str]:
    return {str(key or "").strip().casefold(): str(value or "").strip() for key, value in row.items()}


def _get(row: Mapping[str, str], *names: str) -> str:
    return next((row[name.casefold()] for name in names if row.get(name.casefold(), "") != ""), "")


@dataclass
class ImportSummary:
    rows_scanned: int = 0
    canonical_records: int = 0
    lineage_records: int = 0
    chunks_committed: int = 0
    checks_imported: int = 0
    gates_observed: int = 0


class LegacyImporter:
    def __init__(self, database: str | Path, *, chunk_size: int = 2000) -> None:
        self.database = Path(database)
        self.chunk_size = max(1, int(chunk_size))

    def import_sources(self, sources: Iterable[str | Path]) -> ImportSummary:
        summary = ImportSummary()
        for source in sources:
            path = Path(source)
            with path.open("r", encoding="utf-8-sig", errors="ignore", newline="") as handle:
                reader = csv.DictReader(handle)
                chunk: list[tuple[int, dict[str, str]]] = []
                for source_row, raw in enumerate(reader, start=2):
                    summary.rows_scanned += 1
                    chunk.append((source_row, _normalized_row(raw)))
                    if len(chunk) >= self.chunk_size:
                        self._commit_chunk(path, chunk, summary); chunk = []
                if chunk:
                    self._commit_chunk(path, chunk, summary)
        return summary

    def _commit_chunk(self, source: Path, rows: list[tuple[int, dict[str, str]]], summary: ImportSummary) -> None:
        now = utc_now()
        gate_observations = []
        with sqlite3.connect(self.database) as con:
            for source_row, row in rows:
                expression = _get(row, "expression", "regular", "formula")
                alpha_id = _get(row, "alpha_id", "alphaid", "id")
                if not expression and not alpha_id:
                    continue
                features = extract_features(expression) if expression else extract_features(alpha_id)
                observed_at = _get(row, "utc_iso", "observed_at", "date_created") or None
                legacy_id = "legacy_" + hashlib.sha256(f"{source.resolve()}\0{source_row}\0{alpha_id}\0{features.exact_hash}".encode()).hexdigest()[:24]
                existing = con.execute("SELECT canonical_id FROM legacy_alphas WHERE exact_hash=? AND is_canonical=1 ORDER BY observed_at,source_row LIMIT 1", (features.exact_hash,)).fetchone()
                canonical_id = str(existing[0]) if existing else legacy_id
                is_canonical = int(existing is None)
                settings = {key: _get(row, key) for key in ("region", "universe", "neutralization", "decay", "truncation", "delay") if _get(row, key)}
                metrics = {key: to_float(_get(row, key)) for key in ("sharpe", "fitness", "turnover", "returns", "drawdown", "margin") if _get(row, key)}
                checks = json_object(_get(row, "platform_check_json", "checks_json"), [])
                simulation = json_object(_get(row, "platform_simulation_json", "simulation_json"), {})
                con.execute("""INSERT OR IGNORE INTO legacy_alphas
                    (legacy_id,canonical_id,is_canonical,exact_hash,normalized_expression,expression,alpha_id,source,source_row,observed_at,family,settings_json,metrics_json,checks_json,simulation_json,parse_valid,imported_at)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
                    legacy_id,canonical_id,is_canonical,features.exact_hash,features.normalized_expression,expression,alpha_id,
                    source.name,source_row,observed_at,_get(row,"family"),json.dumps(settings),json.dumps(metrics),
                    json.dumps(checks,ensure_ascii=False),json.dumps(simulation,ensure_ascii=False),int(features.parse_valid),now,
                ))
                lineage_id = hashlib.sha256(f"{canonical_id}\0{legacy_id}".encode()).hexdigest()
                changed = con.execute("INSERT OR IGNORE INTO alpha_lineage(lineage_id,canonical_id,legacy_id,alpha_id,source,relationship,created_at) VALUES (?,?,?,?,?,?,?)", (lineage_id,canonical_id,legacy_id,alpha_id,source.name,"canonical" if is_canonical else "exact_duplicate",now)).rowcount
                summary.lineage_records += changed
                if is_canonical:
                    summary.canonical_records += 1
                    self._store_features(con, canonical_id, features)
                payload = checks if isinstance(checks, dict) else {"checks": checks}
                if isinstance(payload, dict):
                    merged = dict(payload)
                    merged.setdefault("id", alpha_id); merged.setdefault("settings", settings)
                    parsed = parse_gate_observations(merged, observed_at=observed_at, source=source.name)
                    gate_observations.extend(parsed)
                    for index, obs in enumerate(parsed):
                        event_id = hashlib.sha256(f"{legacy_id}\0{index}\0{obs.gate_name}".encode()).hexdigest()
                        summary.checks_imported += con.execute("INSERT OR IGNORE INTO alpha_check_events(event_id,legacy_id,name,result,limit_value,observed_value,raw_json,observed_at) VALUES (?,?,?,?,?,?,?,?)", (event_id,legacy_id,obs.gate_name,obs.result,obs.limit,obs.value,json.dumps(sanitize_payload(payload),ensure_ascii=False),observed_at)).rowcount
            con.commit()
        if gate_observations:
            summary.gates_observed += GateRegistry(self.database).record_many(gate_observations)
        summary.chunks_committed += 1

    @staticmethod
    def _store_features(con: sqlite3.Connection, canonical_id: str, f: ExpressionFeatures) -> None:
        con.execute("""INSERT OR REPLACE INTO alpha_expression_features
            (canonical_id,ast_json,structure_signature,behavior_signature,operators_json,topology,fields_json,field_categories_json,windows_json,grouping_json,normalizers_json,conditions_json,nesting_depth,operator_count,unit_warnings_json)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", (
            canonical_id,f.ast_json,f.structure_signature,f.behavior_signature,json.dumps(f.operators),f.topology,
            json.dumps(f.fields),json.dumps(f.field_categories),json.dumps(f.windows),json.dumps(f.grouping),
            json.dumps(f.normalizers),json.dumps(f.conditions),f.nesting_depth,f.operator_count,json.dumps(f.unit_warnings),
        ))

"""Dynamic-gate legacy classification."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Mapping


@dataclass(frozen=True)
class TriageDecision:
    classification: str
    reason: str


def classify_legacy(record: Mapping[str, Any], *, limits: Mapping[str, float], near_pass_ratio: float = 0.90) -> TriageDecision:
    if not record.get("parse_valid", True) or not record.get("expression", "x"):
        return TriageDecision("ARCHIVE", "invalid_expression")
    if record.get("unit_warnings"):
        return TriageDecision("SEED_ONLY", "unit_warning")
    sharpe, fitness = record.get("sharpe"), record.get("fitness")
    sharpe_limit, fitness_limit = limits.get("LOW_SHARPE"), limits.get("LOW_FITNESS")
    if sharpe is None or fitness is None or sharpe_limit is None or fitness_limit is None:
        return TriageDecision("SEED_ONLY", "missing_metrics_or_gate")
    checks = record.get("checks") if isinstance(record.get("checks"), list) else []
    hard = [check for check in checks if str(check.get("result") or "").upper() in {"FAIL", "FAILED", "ERROR", "REJECTED"}]
    if float(sharpe) >= sharpe_limit and float(fitness) >= fitness_limit and not hard:
        incomplete = not checks or any(str(check.get("result") or "").upper() in {"PENDING", "MISSING", "UNKNOWN", ""} for check in checks)
        return TriageDecision("RECHECK" if incomplete else "SEED_ONLY", "checks_incomplete" if incomplete else "historical_pass_seed")
    if float(sharpe) >= sharpe_limit * near_pass_ratio and float(fitness) >= fitness_limit * near_pass_ratio:
        return TriageDecision("REPAIR", "near_pass")
    return TriageDecision("SEED_ONLY", "below_near_pass")

"""Correlation-matrix medoid utilities."""

from __future__ import annotations

from typing import Mapping


def correlation_medoid(ids: list[str], correlations: Mapping[tuple[str, str], float]) -> str:
    if not ids:
        raise ValueError("ids must not be empty")
    return min(sorted(ids), key=lambda candidate: (sum(1.0 - abs(correlations.get((candidate, other), correlations.get((other, candidate), 0.0))) for other in ids if other != candidate), candidate))

"""Persistent bounded-arm reward accounting for consultant exploration."""

from __future__ import annotations

import hashlib
import json
import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path

from alpha_mining.policy.consultant_policy import ConsultantPolicy


@dataclass(frozen=True)
class BanditArm:
    family: str
    dataset: str
    mutation_type: str
    settings_profile: str

    @property
    def key(self) -> str:
        return "|".join((self.family,self.dataset,self.mutation_type,self.settings_profile))


class ConsultantBandit:
    def __init__(self, database: str | Path, *, policy: ConsultantPolicy | None = None) -> None:
        self.database = Path(database); self.policy = policy or ConsultantPolicy()

    def reward(self, arm: BanditArm, components: dict[str, float | bool]) -> float:
        value = sum(self.policy.reward_weights.get(name, 0.0) * float(component) for name,component in components.items())
        now = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
        event_id = hashlib.sha256(f"{arm.key}\0{now}\0{json.dumps(components,sort_keys=True)}".encode()).hexdigest()
        with sqlite3.connect(self.database) as con:
            con.execute("INSERT INTO consultant_bandit_events(event_id,arm_key,reward,components_json,created_at) VALUES (?,?,?,?,?)", (event_id,arm.key,value,json.dumps(components,sort_keys=True),now))
        return value

    def scores(self) -> dict[str, float]:
        with sqlite3.connect(self.database) as con:
            return {key: float(value) for key,value in con.execute("SELECT arm_key,AVG(reward) FROM consultant_bandit_events GROUP BY arm_key")}

"""Fail-closed submission guard for consultant candidates."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

INCOMPLETE = frozenset({"PENDING","MISSING","UNKNOWN","ERROR","", "NONE"})
FAILURES = frozenset({"FAIL","FAILED","REJECTED"})


@dataclass(frozen=True)
class CandidateContext:
    alpha_id: str
    expression_id: str
    checks: list[dict[str, Any]]
    gate_snapshots_fresh: bool
    quality_buffer_pass: bool
    local_correlation_status: str
    unit_warnings: tuple[str, ...] = ()
    concentration_failure: bool = False
    duplicate: bool = False
    submitted_cluster: bool = False
    mandatory_checks: tuple[str, ...] = ("LOW_SHARPE",)
    competition_required: bool = False
    theme_required: bool = False
    pyramid_required: bool = False


@dataclass(frozen=True)
class GuardDecision:
    allowed: bool
    reasons: tuple[str, ...]


class SubmissionGuard:
    def evaluate(self, context: CandidateContext) -> GuardDecision:
        reasons: list[str] = []
        by_name = {str(check.get("name") or "").upper(): str(check.get("result") or check.get("status") or "UNKNOWN").upper() for check in context.checks if isinstance(check, dict)}
        for name in context.mandatory_checks:
            status = by_name.get(name.upper(), "MISSING")
            if status != "PASS":
                reasons.append(f"MANDATORY_{name.upper()}_{status}")
        self_status = by_name.get("SELF_CORRELATION", "MISSING")
        if self_status != "PASS":
            reasons.append(f"SELF_CORRELATION_{self_status}")
        if "PROD_CORRELATION" in by_name and by_name["PROD_CORRELATION"] != "PASS":
            reasons.append(f"PROD_CORRELATION_{by_name['PROD_CORRELATION']}")
        for required, name in ((context.competition_required,"MATCHES_COMPETITION"),(context.theme_required,"MATCHES_THEME"),(context.pyramid_required,"MATCHES_PYRAMID")):
            if required and by_name.get(name,"MISSING") != "PASS":
                reasons.append(f"{name}_{by_name.get(name,'MISSING')}")
        for name,status in by_name.items():
            if status in INCOMPLETE | FAILURES and not any(reason.startswith(name) or name in reason for reason in reasons):
                reasons.append(f"CHECK_{name or 'UNKNOWN'}_{status}")
        if not context.gate_snapshots_fresh: reasons.append("GATE_SNAPSHOT_STALE_OR_MISSING")
        if not context.quality_buffer_pass: reasons.append("QUALITY_BUFFER_FAILED")
        local = context.local_correlation_status.upper()
        if local == "INSUFFICIENT_HISTORY": reasons.append("LOCAL_CORRELATION_INSUFFICIENT_HISTORY")
        elif local != "PASS": reasons.append(f"LOCAL_CORRELATION_{local or 'MISSING'}")
        if context.unit_warnings: reasons.append("UNIT_WARNING")
        if context.concentration_failure: reasons.append("CONCENTRATION_FAILURE")
        if context.duplicate: reasons.append("DUPLICATE")
        if context.submitted_cluster: reasons.append("SUBMITTED_CLUSTER")
        return GuardDecision(not reasons, tuple(dict.fromkeys(reasons)))

"""Behavior-first mutation admission policy."""

from __future__ import annotations

from dataclasses import dataclass

from alpha_mining.domain.expression_normalization import behavior_signature, extract_fields, extract_functions


@dataclass(frozen=True)
class MutationDecision:
    allowed: bool
    reason: str


class MutationPolicy:
    def assess(self, parent: str, child: str, *, parent_settings: dict | None = None, child_settings: dict | None = None) -> MutationDecision:
        if not child.strip() or child.strip() == parent.strip():
            return MutationDecision(False, "IDENTICAL")
        if behavior_signature(parent, settings=parent_settings) == behavior_signature(child, settings=child_settings):
            return MutationDecision(False, "BEHAVIOR_EQUIVALENT")
        if set(extract_fields(parent)) == set(extract_fields(child)) and extract_functions(parent) == extract_functions(child):
            return MutationDecision(False, "PARAMETER_ONLY")
        return MutationDecision(True, "BEHAVIOR_DIFFERENT")

"""Robustness scoring over one-parameter-at-a-time trials."""

from __future__ import annotations


def robustness_score(trials: list[dict]) -> float:
    if not trials:
        return 0.0
    passed = sum(bool(trial.get("quality_buffer_pass")) for trial in trials) / len(trials)
    worst_margin = min(float(trial.get("normalized_margin", 0.0)) for trial in trials)
    return max(0.0, min(1.0, 0.5 * passed + 0.5 * max(0.0, worst_margin)))

"""Configuration-only safety margins; platform limits remain dynamic."""

from __future__ import annotations

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


@dataclass(frozen=True)
class ConsultantPolicy:
    gate_freshness_hours: float = 24.0
    quality_margin: float = 0.05
    turnover_margin: float = 0.01
    correlation_margin: float = 0.03
    correlation_ceiling: float = 0.65
    near_pass_ratio: float = 0.90
    min_correlation_overlap: int = 60
    max_candidates_per_hypothesis: int = 8
    max_behavior_per_round: int = 2
    max_parent_offspring: int = 8
    hard_parent_offspring: int = 12
    max_settings_trials: int = 6
    simulation_budget: int = 64
    execute_submit: bool = False
    confirmation_phrase: str = "I_UNDERSTAND_REAL_SUBMISSION"
    reward_weights: dict[str, float] = field(default_factory=lambda: {
        "platform_pass": 4.0, "quality_buffer": 2.0, "novelty": 1.5,
        "robustness": 1.5, "sub_universe_margin": 1.0, "simulation_cost": -1.0,
        "duplicate": -2.0, "unit_failure": -2.0, "concentration": -2.0,
    })

    @classmethod
    def from_file(cls, path: str | Path | None) -> "ConsultantPolicy":
        if not path or not Path(path).is_file():
            return cls()
        try:
            import yaml
            raw = yaml.safe_load(Path(path).read_text(encoding="utf-8")) or {}
        except Exception:
            return cls()
        section: dict[str, Any] = raw.get("consultant", raw) if isinstance(raw, dict) else {}
        allowed = set(cls.__dataclass_fields__)
        return cls(**{key: value for key, value in section.items() if key in allowed})

    def internal_limit(self, *, live_limit: float, direction: str, gate_name: str) -> float:
        if "CORRELATION" in gate_name.upper():
            return min(float(live_limit) - self.correlation_margin, self.correlation_ceiling)
        if "TURNOVER" in gate_name.upper():
            return float(live_limit) + self.turnover_margin if direction.upper() == "MIN" else float(live_limit) - self.turnover_margin
        return float(live_limit) + self.quality_margin if direction.upper() == "MIN" else float(live_limit) - self.quality_margin

"""Dynamic consultant quality-buffer judge."""

from __future__ import annotations

from alpha_mining.policy.consultant_policy import ConsultantPolicy


def quality_buffer_pass(metrics: dict[str,float], gates: dict[str,tuple[float,str]], *, policy: ConsultantPolicy | None = None) -> tuple[bool, list[str]]:
    policy = policy or ConsultantPolicy(); reasons = []
    mapping = {"LOW_SHARPE":"sharpe","LOW_FITNESS":"fitness","LOW_TURNOVER":"turnover","HIGH_TURNOVER":"turnover"}
    for gate,(limit,direction) in gates.items():
        key = mapping.get(gate.upper())
        if not key or metrics.get(key) is None:
            continue
        internal = policy.internal_limit(live_limit=limit,direction=direction,gate_name=gate)
        value = float(metrics[key])
        if (direction.upper() == "MIN" and value < internal) or (direction.upper() == "MAX" and value > internal):
            reasons.append(gate.upper())
    return not reasons, reasons

"""Three-stage settings selection without Cartesian-product search."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class SettingTrial:
    profile: str
    settings: dict[str, Any]
    parameter_delta: dict[str, Any]


class SettingsOptimizer:
    def __init__(self, *, max_local_trials: int = 6, total_budget: int = 64) -> None:
        self.max_local_trials = max(0, int(max_local_trials)); self.total_budget = max(0, int(total_budget)); self.consumed = 0

    def stage1_default(self, family: str, priors: list[dict] | None = None) -> dict[str, Any]:
        defaults = {"region":"USA","universe":"TOP3000","delay":1,"neutralization":"SUBINDUSTRY","decay":0,"truncation":0.08,"nanHandling":"ON","pasteurization":"ON"}
        viable = sorted(priors or [], key=lambda item: (float(item.get("smoothed_success",0)), -float(item.get("simulation_cost",0))), reverse=True)
        return {**defaults, **(viable[0].get("settings", {}) if viable else {})}

    def local_trials(self, base: dict[str, Any], *, quality_score: float, metric_ratio: float, delay_allowed: bool = False) -> list[SettingTrial]:
        if quality_score < 0.7 and metric_ratio < 0.90:
            return []
        candidates = [
