from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

import requests

from alpha_mining.auth.session_manager import AuthSettings, ensure_authenticated

BASE_URL = "https://api.worldquantbrain.com"


class PlatformReadError(RuntimeError):
    pass


@dataclass
class ReadOnlyPlatformClient:
    state_path: str | Path = ".wq_auth_state.json"
    timeout: float = 30.0

    def __post_init__(self) -> None:
        self.session = requests.Session()

    def authenticate(self) -> None:
        username = os.environ.get("WQ_USERNAME", "").strip()
        password = os.environ.get("WQ_PASSWORD", "")
        if not username:
            raise PlatformReadError("WQ_USERNAME is required to match the protected auth-state fingerprint")
        def login() -> Any:
            if not password:
                raise PlatformReadError("protected session unavailable and WQ_PASSWORD is not configured")
            return self.session.post(f"{BASE_URL}/authentication", auth=(username,password), timeout=self.timeout)
        ensure_authenticated(self.session,login,username,AuthSettings(state_path=self.state_path))

    def fetch_alpha(self, alpha_id: str) -> dict[str, Any]:
        response = self.session.get(f"{BASE_URL}/alphas/{alpha_id}",timeout=self.timeout)
        if response.status_code != 200:
            raise PlatformReadError(f"read-only alpha detail failed with HTTP {response.status_code}")
        payload = response.json()
        if not isinstance(payload,dict):
            raise PlatformReadError("alpha detail response is not an object")
        return payload

    def fetch_many(self, alpha_ids: Iterable[str]) -> list[dict[str, Any]]:
        self.authenticate()
        return [self.fetch_alpha(alpha_id) for alpha_id in alpha_ids if str(alpha_id).strip()]

